<div class="page-header"><div><h2><?= e($workshop['name']) ?></h2><p><?= e($workshop['description']) ?></p><p><strong>Responsável:</strong> <?= e($workshop['responsible_name']??'Não definido') ?></p></div><div class="actions"><a class="btn btn-secondary" href="<?= e(url('/oficinas')) ?>">Voltar</a><?php if(is_professor()): ?><a class="btn btn-primary" href="<?= e(url('/oficinas/'.$workshop['id'].'/editar')) ?>">Editar Oficina</a><?php endif; ?></div></div>
<?php if(!empty($workshop['image_path'])): ?><img class="workshop-hero" src="<?= e(url($workshop['image_path'])) ?>" alt="<?= e($workshop['name']) ?>"><?php else: ?><div class="workshop-hero fallback" style="background:<?= e($workshop['color']??'#4f46e5') ?>">GA</div><?php endif; ?>
<div class="grid two"><section class="panel"><div class="panel-header"><h3>Alunos vinculados</h3></div><div class="panel-body"><?php foreach($participants as $s): ?><div class="metric-line"><span><a class="text-link" href="<?= e(url('/alunos/'.$s['id'])) ?>"><strong><?= e($s['full_name']) ?></strong></a></span><?php if(is_professor()): ?><form method="POST" action="<?= e(url('/oficinas/'.$workshop['id'].'/participantes/'.$s['id'].'/remover')) ?>" data-confirm="Remover este aluno da oficina?"><?= csrf_field() ?><button class="btn btn-danger">Remover</button></form><?php endif; ?></div><?php endforeach; ?><?php if(!$participants): ?><div class="empty">Nenhum aluno vinculado.</div><?php endif; ?>
<?php if(is_professor() && $availableParticipants): ?><hr><form class="form" method="POST" action="<?= e(url('/oficinas/'.$workshop['id'].'/participantes')) ?>"><?= csrf_field() ?><div class="form-group"><label>Adicionar aluno</label><select class="select" name="student_id" required><option value="">Selecione</option><?php foreach($availableParticipants as $s): ?><option value="<?= e($s['id']) ?>"><?= e($s['full_name']) ?> — ID #<?= e($s['id']) ?></option><?php endforeach; ?></select></div><button class="btn btn-primary">Adicionar Aluno</button></form><?php endif; ?></div></section>
<section class="panel"><div class="panel-header"><h3>Histórico de produção</h3></div><div class="panel-body"><div class="feed-list"><?php foreach($productions as $p): ?><div class="feed-item"><strong><?= e($p['product_name']) ?></strong><span><?php if($p['student_name']): ?><a class="text-link" href="<?= e(url('/alunos/'.$p['student_id'])) ?>"><?= e($p['student_name']) ?></a> — Trabalho nº <?= e($p['work_number']) ?><?php else: ?>Registro antigo sem aluno<?php endif; ?></span><small><?= e(date('d/m/Y',strtotime($p['produced_at']))) ?> · Quantidade <?= e($p['quantity']) ?></small></div><?php endforeach; ?><?php if(!$productions): ?><div class="empty">Nenhuma produção nesta oficina.</div><?php endif; ?></div></div></section></div>
